import subprocess
import os
import glob
import time
import sys
def task_func(test_dir):
    if not isinstance(test_dir, str):
        raise TypeError("test_dir must be a string")
    if not test_dir or not os.path.isdir(test_dir):
        raise OSError("Invalid test_dir")
    test_dir = os.path.normpath(test_dir)
    pattern = os.path.join(test_dir, "*.py")
    scripts = glob.glob(pattern)
    results = {}
    for script in scripts:
        start = time.time()
        try:
            subprocess.run([sys.executable, script], check=False)
        except Exception:
            continue
        end = time.time()
        results[os.path.basename(script)] = end - start
    return results

