import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time >= duration:
            break
        timestamp = now
        cpu_usage = None
        try:
            if system.startswith("win"):
                cmd = ['typeperf', r'\Processor(_Total)\% Processor Time', '-sc', '1']
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if proc.returncode == 0 and out:
                    lines = out.decode(errors='ignore').strip().splitlines()
                    if len(lines) >= 3:
                        data_line = lines[2]
                        parts = data_line.split(',')
                        if len(parts) >= 2:
                            value_str = parts[1].strip().strip('"')
                            cpu_usage = float(value_str)
            else:
                cmd = ['top', '-b', '-n', '1']
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if proc.returncode == 0 and out:
                    lines = out.decode(errors='ignore').splitlines()
                    for line in lines:
                        if 'Cpu(s)' in line or 'CPU:' in line or 'Cpu0' in line:
                            if 'id' in line:
                                parts = line.replace('%', '').split(',')
                                idle_val = None
                                for p in parts:
                                    if 'id' in p:
                                        num_part = ''.join(ch for ch in p if (ch.isdigit() or ch == '.' or ch == '-'))
                                        if num_part:
                                            idle_val = float(num_part)
                                        break
                                if idle_val is not None:
                                    cpu_usage = 100.0 - idle_val
                            break
        except Exception:
            cpu_usage = None
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        elapsed = time.time() - start_time
        if elapsed >= duration:
            break
        sleep_time = interval
        remaining = duration - elapsed
        if remaining < sleep_time:
            sleep_time = remaining
        if sleep_time > 0:
            time.sleep(sleep_time)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH

import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    records = []
    start_time = time.time()
    system_name = platform.system()
    while True:
        now = time.time()
        if now - start_time >= duration and records:
            break
        try:
            if system_name == "Windows":
                result = subprocess.run(["wmic", "cpu", "get", "loadpercentage"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                output = result.stdout.strip().splitlines()
                cpu_usage = None
                for line in output:
                    line = line.strip()
                    if not line or line.lower().startswith("loadpercentage"):
                        continue
                    try:
                        cpu_usage = float(line)
                        break
                    except ValueError:
                        continue
                if cpu_usage is None:
                    cpu_usage = 0.0
            else:
                result = subprocess.run(["sh", "-c", "top -bn1 | grep '%Cpu' || top -bn1 | grep Cpu"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                line = result.stdout.strip()
                cpu_usage = 0.0
                if line:
                    parts = line.replace(",", ".").split()
                    for i, part in enumerate(parts):
                        if "%id" in part or "id," in part or "id" == part:
                            try:
                                idle_str = parts[i - 1]
                                idle = float(idle_str)
                                cpu_usage = 100.0 - idle
                            except Exception:
                                cpu_usage = 0.0
                            break
            records.append({"timestamp": now, "cpu_usage": cpu_usage})
        except Exception:
            records.append({"timestamp": now, "cpu_usage": 0.0})
        time.sleep(interval)
        if time.time() - start_time >= duration:
            break
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
