import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise OSError("Invalid script path")
    start_time = time.time()
    process = subprocess.Popen(["bash", script_path])
    ps_proc = psutil.Process(process.pid)
    cpu_usage_total = 0.0
    mem_usage_total = 0
    try:
        ps_proc.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        process.kill()
        return {"CPU Usage": cpu_usage_total, "Memory Usage": mem_usage_total}
    while True:
        if time.time() - start_time > timeout:
            try:
                process.terminate()
            except Exception:
                pass
            break
        if process.poll() is not None:
            try:
                if ps_proc.status() == psutil.STATUS_ZOMBIE:
                    break
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
        try:
            time.sleep(0.1)
            cpu = ps_proc.cpu_percent(interval=None)
            try:
                mem = ps_proc.memory_info().rss
            except psutil.ZombieProcess:
                break
            cpu_usage_total += cpu
            mem_usage_total += mem
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
        if process.poll() is not None:
            break
    if process.poll() is None:
        try:
            process.terminate()
        except Exception:
            pass
        try:
            process.wait(timeout=1)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
    return {"CPU Usage": cpu_usage_total, "Memory Usage": mem_usage_total}

