import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    os.makedirs(ARCHIVE_DIR, exist_ok=True)
    files = glob.glob(pattern)
    if not files:
        raise FileNotFoundError("No files match the given pattern")
    base_name = os.path.basename(pattern)
    if not base_name or base_name in ("*", "?.*"):
        archive_name = "archive.tar.gz"
    else:
        archive_name = base_name.replace("*", "STAR").replace("?", "Q") + ".tar.gz"
    archive_path = os.path.join(ARCHIVE_DIR, archive_name)
    cmd = ["tar", "-czf", archive_path] + files
    result = subprocess.run(cmd)
    if result.returncode != 0:
        raise OSError("Failed to create archive")
    for f in files:
        try:
            os.remove(f)
        except FileNotFoundError:
            continue
    return archive_path

import subprocess
import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR, exist_ok=True)
    files = glob.glob(pattern)
    archive_name = 'archive.tar.gz'
    archive_path = os.path.join(ARCHIVE_DIR, archive_name)
    if files:
        cmd = ['tar', '-czf', archive_path]
        cmd.extend(files)
        try:
            subprocess.check_call(cmd)
        except Exception:
            return archive_path
        for f in files:
            try:
                os.remove(f)
            except Exception:
                pass
    else:
        open(archive_path, 'a').close()
    return archive_path
